style.css:
/* ==UserStyle==
@name           ЦИАН — Dark Theme
@namespace      cian-dark
@version        1.0.0
==/UserStyle== */

html,
body {
    background: #121212 !important;
    color: #e8e8e8 !important;
}

/* Основной фон */
body,
main,
header,
footer {
    background-color: #121212 !important;
}

/* Все основные контейнеры и карточки */
div,
section,
article {
    border-color: #2d2d2d !important;
}

/* Карточки объявлений */
[data-testid*="card"],
[class*="card"],
[class*="Card"] {
    background: #1b1b1b !important;
    color: #e8e8e8 !important;
    border-color: #303030 !important;
}

/* Текст */
p,
span,
div,
h1,
h2,
h3,
h4,
h5,
h6,
label {
    color: inherit;
}

/* Поля поиска и ввода */
input,
textarea,
select {
    background: #1e1e1e !important;
    color: #eeeeee !important;
    border-color: #3a3a3a !important;
}

input::placeholder,
textarea::placeholder {
    color: #888 !important;
}

/* Кнопки */
button {
    background-color: #242424 !important;
    color: #eeeeee !important;
    border-color: #3a3a3a !important;
}

button:hover {
    background-color: #303030 !important;
}

/* Ссылки */
a {
    color: #b8b8b8 !important;
}

a:hover {
    color: #ffffff !important;
}

/* Выпадающие меню */
[role="menu"],
[role="dialog"],
[class*="popover"],
[class*="Popover"],
[class*="dropdown"],
[class*="Dropdown"] {
    background: #1b1b1b !important;
    color: #eeeeee !important;
    border-color: #333 !important;
}

/* Модальные окна */
[role="dialog"] {
    box-shadow: 0 10px 40px rgba(0, 0, 0, .6) !important;
}

/* Разделители */
hr {
    border-color: #303030 !important;
}

/* Скроллбар */
::-webkit-scrollbar {
    width: 10px;
    height: 10px;
}

::-webkit-scrollbar-track {
    background: #121212;
}

::-webkit-scrollbar-thumb {
    background: #3a3a3a;
    border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
    background: #505050;
}

/* Изображения не затемнять */
img {
    opacity: 1 !important;
}

/* Карта */
[class*="map"],
[class*="Map"] {
    filter: brightness(.75) contrast(1.05);
}
